APPROVAL_BATCH_SIZE = 250
APPROVAL_RETRY_ATTEMPTS = 5
_HEX64 = re.compile(r"^[0-9a-f]{64}$")
_HEX128 = re.compile(r"^[0-9a-f]{128}$")

# The server replaces these exact markers in the customized one-file download.
# The public, readable copy intentionally contains no workspace capability.
EMBEDDED_BASE_URL = "__INFRAVEIL_BASE_URL__"
EMBEDDED_BOOTSTRAP_TOKEN = "__INFRAVEIL_BOOTSTRAP_TOKEN__"
EMBEDDED_USERNAME = "__INFRAVEIL_USERNAME__"
EMBEDDED_LAUNCHER_HOST_ID = "__INFRAVEIL_LAUNCHER_HOST_ID__"
EMBEDDED_RELEASE_PUBLIC_KEY = "__INFRAVEIL_RELEASE_PUBLIC_KEY__"


def _embedded(value, fallback=""):
    value = str(value or "").strip()
    return fallback if value.startswith("__INFRAVEIL_") else value


DEFAULT_BASE_URL = _embedded(EMBEDDED_BASE_URL, "https://portal.infraveil.com")
BOOTSTRAP_TOKEN = _embedded(EMBEDDED_BOOTSTRAP_TOKEN)
WORKSPACE_USERNAME = _embedded(EMBEDDED_USERNAME)
LAUNCHER_HOST_ID = _embedded(EMBEDDED_LAUNCHER_HOST_ID)
RELEASE_PUBLIC_KEY = _embedded(EMBEDDED_RELEASE_PUBLIC_KEY).lower()


_C = {
    "d": "\x1b[0m",
    "b": "\x1b[1m",
    "dim": "\x1b[90m",
    "g": "\x1b[92m",
    "y": "\x1b[93m",
    "r": "\x1b[91m",
    "c": "\x1b[96m",
}


def _col(value, key):
    return _C.get(key, "") + str(value) + _C["d"]


def _enable_ansi():
    if os.name == "nt":
        try:
            import ctypes

            kernel = ctypes.windll.kernel32
            kernel.SetConsoleMode(kernel.GetStdHandle(-11), 7)
        except Exception:
            pass


def _control_home(value=None):
    configured = str(value or os.environ.get("INFRAVEIL_CONTROL_HOME") or "").strip()
    if configured:
        return os.path.abspath(os.path.expanduser(configured))
    script_dir = os.path.dirname(os.path.realpath(__file__))
    working_dir = os.path.abspath(os.getcwd())
    if os.path.basename(script_dir).lower() == CONTROL_DIR_NAME.lower():
        return script_dir
    if os.path.basename(working_dir).lower() == CONTROL_DIR_NAME.lower():
        return working_dir
    return os.path.join(working_dir, CONTROL_DIR_NAME)


def _path(home, name):
    return os.path.join(home, name)


_WINDOWS_SID = ""


def _windows_current_sid():
    global _WINDOWS_SID
    if _WINDOWS_SID:
        return _WINDOWS_SID
    try:
        output = subprocess.check_output(
            ["whoami", "/user", "/fo", "csv", "/nh"],
            text=True,
            stderr=subprocess.DEVNULL,
            timeout=15,
        )
    except Exception as exc:
        raise RuntimeError("Could not identify the current Windows account for private-file ACLs") from exc
    match = re.search(r"S-\d+(?:-\d+)+", output, re.IGNORECASE)
    if not match:
        raise RuntimeError("Windows did not return a valid current-user SID")
    _WINDOWS_SID = match.group(0)
    return _WINDOWS_SID


def _restrict_windows_acl(path, directory=False):
    sid = _windows_current_sid()
    permission = f"*{sid}:(OI)(CI)F" if directory else f"*{sid}:F"
    result = subprocess.run(
        ["icacls", os.path.abspath(path), "/inheritance:r", "/grant:r", permission],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
        timeout=30,
    )
    if result.returncode != 0:
        detail = (result.stderr or "").strip()[:160]
        raise RuntimeError(f"Could not restrict Windows ACL for {path}: {detail or 'icacls failed'}")


def _secure_dir(path):
    absolute = os.path.abspath(path)
    if os.path.lexists(absolute) and os.path.islink(absolute):
        raise RuntimeError(f"Refusing symlinked private directory: {absolute}")
    os.makedirs(absolute, mode=0o700, exist_ok=True)
    if os.name == "nt":
        _restrict_windows_acl(absolute, directory=True)
    else:
        os.chmod(absolute, 0o700)


def _secure_write(path, value):
    parent = os.path.dirname(os.path.abspath(path))
    _secure_dir(parent)
    temporary = path + "." + os.urandom(8).hex() + ".tmp"
    # Signed source is an exact byte contract. Text-mode writes translate
    # LF to CRLF on Windows and would invalidate a verified source hash.
    data = value if isinstance(value, bytes) else value.encode("utf-8")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    descriptor = os.open(temporary, flags, 0o600)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        if os.name == "nt":
            _restrict_windows_acl(temporary, directory=False)
        else:
            os.chmod(temporary, 0o600)
        os.replace(temporary, path)
        if os.name == "nt":
            _restrict_windows_acl(path, directory=False)
    except Exception:
        try:
            os.remove(temporary)
        except OSError:
            pass
        raise


def _read_secret_file(path, label):
    try:
        stat = os.stat(path)
        if os.name == "nt":
            _restrict_windows_acl(path, directory=False)
        elif stat.st_mode & 0o077:
            raise RuntimeError(f"{label} is readable by other users: chmod 600 {path}")
    except FileNotFoundError as exc:
        raise RuntimeError(f"{label} file not found: {path}") from exc
    with open(path, encoding="utf-8") as handle:
        return handle.read().strip()


def _default_config(home):
    return {
        "base_url": DEFAULT_BASE_URL,
        "policy": "manual",
        "key_file": _path(home, "approval-private.key"),
        "token_file": _path(home, "approval-token.txt"),
        "allowlist_file": _path(home, "approved-hashes.txt"),
        "log": _path(home, "approval-decisions.log"),
        "interval": 30,
        "launcher_file": _path(home, os.path.join("runtime", "launcher.py")),
        "workspace_username": WORKSPACE_USERNAME,
        "launcher_host_id": LAUNCHER_HOST_ID,
        "pending_install_token": "",
        "pending_install_url": "",
        "pending_install_expires_at": 0,
    }


def _config_path(home):
    return _path(home, "trust-console.json")


def _load_config(home):
    config = _default_config(home)
    try:
        with open(_config_path(home), encoding="utf-8") as handle:
            loaded = json.load(handle)
        if isinstance(loaded, dict):
            config.update(loaded)
    except FileNotFoundError:
        pass
    except Exception as exc:
        print(_col(f"warning: could not read configuration: {exc}", "y"))
    return config


def _save_config(home, config):
    _secure_write(_config_path(home), json.dumps(config, indent=2, sort_keys=True) + "\n")


def _installed_script(home):
    return _path(home, "infraveil.py")


def _install_self(home):
    source_path = os.path.realpath(__file__)
    destination = _installed_script(home)
    if os.path.abspath(source_path) == os.path.abspath(destination):
        return destination
    with open(source_path, encoding="utf-8") as handle:
        source = handle.read()
    _secure_write(destination, source)
    if os.name != "nt":
        os.chmod(destination, 0o700)
    return destination


def _venv_python(home):
    return _path(_managed_runtime_directory(home), os.path.join("Scripts" if os.name == "nt" else "bin", "python.exe" if os.name == "nt" else "python"))


def _runtime_ready():
    try:
        for requirement, _hashes in LOCKED_WHEEL_HASHES:
            distribution, expected_version = requirement.split("==", 1)
            if importlib.metadata.version(distribution) != expected_version:
                return False
        for name in ("requests", "cryptography", "psutil", "waitress", "aiohttp"):
            importlib.import_module(name)
        return True
    except (ImportError, importlib.metadata.PackageNotFoundError, ValueError):
        return False


def _runtime_probe_code():
    expected = dict(requirement.split("==", 1) for requirement, _hashes in LOCKED_WHEEL_HASHES)
    return (
        "import importlib.metadata as metadata; "
        f"expected={expected!r}; "
        "assert all(metadata.version(name) == version for name, version in expected.items()); "
        "import requests, cryptography, psutil, waitress, aiohttp"
    )


def _sanitized_runtime_env(home):
    env = os.environ.copy()
    for name in list(env):
        upper = name.upper()
        if upper.startswith("PYTHON") or upper.startswith("PIP_"):
            env.pop(name, None)
    for name in ("REQUESTS_CA_BUNDLE", "CURL_CA_BUNDLE", "SSL_CERT_FILE", "SSL_CERT_DIR"):
        env.pop(name, None)
    env.pop("VIRTUAL_ENV", None)
    env.pop("__PYVENV_LAUNCHER__", None)
    env.update({
        "PIP_CONFIG_FILE": os.devnull,
        "PIP_DISABLE_PIP_VERSION_CHECK": "1",
        "PIP_NO_INPUT": "1",
        "PIP_REQUIRE_VIRTUALENV": "1",
        "PYTHONNOUSERSITE": "1",
        "INFRAVEIL_TRUST_CONSOLE_RUNTIME": "1",
        "INFRAVEIL_CONTROL_HOME": home,
        "INFRAVEIL_MANAGED_RUNTIME_HOME": os.path.abspath(home),
        "INFRAVEIL_RUNTIME_LOCK_SHA256": _runtime_lock_identity(),
    })
    return env


def _locked_requirements_text():
    lines = [
        "# Reviewed official and private native release wheels; wheel-only and hash-locked.",
        "# Infraveil Trust Console runtime lock v1.",
    ]
    for requirement, hashes in LOCKED_WHEEL_HASHES:
        lines.append(requirement + " \\")
        for index, digest in enumerate(hashes):
            suffix = " \\" if index < len(hashes) - 1 else ""
            lines.append("    --hash=sha256:" + digest + suffix)
    return "\n".join(lines) + "\n"


def _runtime_lock_identity():
    contract = {requirement: sorted(hashes) for requirement, hashes in LOCKED_WHEEL_HASHES}
    return hashlib.sha256(json.dumps(contract, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _managed_runtime_directory(home):
    return _path(os.path.abspath(home), ".venv-" + _runtime_lock_identity()[:24])


def _windows_path_owner_sid(path):
    import ctypes
    owner, descriptor, text = ctypes.c_void_p(), ctypes.c_void_p(), ctypes.c_void_p()
    advapi = ctypes.WinDLL("advapi32", use_last_error=True)
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    advapi.GetNamedSecurityInfoW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint, ctypes.c_uint, ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    advapi.GetNamedSecurityInfoW.restype = ctypes.c_uint
    advapi.ConvertSidToStringSidW.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    advapi.ConvertSidToStringSidW.restype = ctypes.c_int
    kernel.LocalFree.argtypes = [ctypes.c_void_p]
    kernel.LocalFree.restype = ctypes.c_void_p
    try:
        code = advapi.GetNamedSecurityInfoW(os.path.abspath(path), 1, 1, ctypes.byref(owner), None, None, None, ctypes.byref(descriptor))
        if code or not advapi.ConvertSidToStringSidW(owner, ctypes.byref(text)):
            raise RuntimeError("Could not verify the managed runtime path owner")
        return ctypes.wstring_at(text)
    finally:
        if text.value:
            kernel.LocalFree(text)
        if descriptor.value:
            kernel.LocalFree(descriptor)


def _assert_runtime_path(path, directory=False, private=True):
    absolute = os.path.abspath(path)
    current = absolute
    while True:
        if os.path.lexists(current):
            info = os.lstat(current)
            if os.path.islink(current) or bool(getattr(info, "st_file_attributes", 0) & 0x400):
                raise RuntimeError("Managed runtime path contains a link or reparse point")
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent
    if os.path.lexists(absolute):
        info = os.lstat(absolute)
        if directory and not os.path.isdir(absolute):
            raise RuntimeError("Managed runtime directory is not a directory")
        if not directory and not os.path.isfile(absolute):
            raise RuntimeError("Managed runtime marker is not a regular file")
        if os.name != "nt" and info.st_uid != os.geteuid():
            raise RuntimeError("Managed runtime path belongs to another account")
        if os.name == "nt" and _windows_path_owner_sid(absolute) != _windows_current_sid():
            raise RuntimeError("Managed runtime path belongs to another Windows account")
        if os.name != "nt" and info.st_mode & (0o077 if private else 0o022):
            raise RuntimeError("Managed runtime path is not private")
    return absolute


def _private_runtime_directory(path):
    absolute = os.path.abspath(path)
    _assert_runtime_path(absolute, directory=True)
    _secure_dir(absolute)
    return _assert_runtime_path(absolute, directory=True)


def _runtime_marker(home):
    directory = _managed_runtime_directory(home)
    _assert_runtime_path(home, directory=True)
    _assert_runtime_path(directory, directory=True)
    marker = _path(directory, ".infraveil-runtime.json")
    if not os.path.lexists(marker):
        return None
    _assert_runtime_path(_venv_python(home), private=False)
    _assert_runtime_path(marker)
    if os.path.getsize(marker) > 65536:
        raise RuntimeError("Managed runtime marker is oversized")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    with os.fdopen(os.open(marker, flags), "r", encoding="utf-8") as handle:
        value = json.load(handle)
    expected_versions = dict(requirement.split("==", 1) for requirement, _hashes in LOCKED_WHEEL_HASHES)
    if not isinstance(value, dict) or value.get("schema") != 1 or value.get("lock_sha256") != _runtime_lock_identity() or value.get("versions") != expected_versions or value.get("runtime_home") != os.path.abspath(home) or value.get("python") != _venv_python(home):
        raise RuntimeError("Managed runtime marker does not match this approved dependency lock")
    return value


def _current_runtime_matches(home):
    directory = _managed_runtime_directory(home)
    if os.path.normcase(os.path.abspath(sys.prefix)) != os.path.normcase(directory) or sys.prefix == sys.base_prefix:
        return False
    return _runtime_marker(home) is not None and _runtime_ready()


def _prepare_runtime(home):
    if sys.version_info < MINIMUM_PYTHON:
        required = ".".join(str(value) for value in MINIMUM_PYTHON)
        raise RuntimeError(f"Python {required} or newer is required; found {platform.python_version()}")
    home = _private_runtime_directory(home)
    directory = _managed_runtime_directory(home)
    venv_python = _venv_python(home)
    env = _sanitized_runtime_env(home)
    lock_path = _path(home, ".prepare-" + _runtime_lock_identity()[:24] + ".lock")
    deadline = time.monotonic() + 30
    while True:
        try:
            os.mkdir(lock_path, 0o700)
            _private_runtime_directory(lock_path)
            break
        except FileExistsError:
            _assert_runtime_path(lock_path, directory=True)
            if time.monotonic() >= deadline:
                raise RuntimeError("Managed runtime preparation is busy; review the private preparation lock before retrying")
            time.sleep(0.1)
    try:
        marker = _runtime_marker(home)
        if marker is not None:
            check = subprocess.run([venv_python, "-I", "-c", _runtime_probe_code()], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False, cwd=home, env=env, timeout=30)
            if check.returncode != 0:
                raise RuntimeError("Published managed runtime failed its lock check; it will not be modified while it may be running")
            return venv_python
        _private_runtime_directory(directory)
        if not os.path.exists(venv_python):
            subprocess.check_call([sys.executable, "-I", "-m", "venv", "--copies", directory], cwd=home, env=env, timeout=120)
        _assert_runtime_path(venv_python, private=False)
        requirements_path = _path(directory, LOCK_FILE_NAME)
        _secure_write(requirements_path, _locked_requirements_text())
        subprocess.check_call([venv_python, '-I', '-m', 'pip', '--isolated', 'install', '--quiet', '--only-binary=:all:', '--require-hashes', '--index-url', 'https://pypi.org/simple', '--find-links', RUNTIME_WHEEL_INDEX, '--requirement', requirements_path], cwd=home, env=env, timeout=300)
        check = subprocess.run([venv_python, "-I", "-c", _runtime_probe_code()], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False, cwd=home, env=env, timeout=30)
        if check.returncode != 0:
            raise RuntimeError("Prepared managed runtime does not match the approved dependency lock")
        marker = {"schema": 1, "lock_sha256": _runtime_lock_identity(), "versions": dict(requirement.split("==", 1) for requirement, _hashes in LOCKED_WHEEL_HASHES), "runtime_home": home, "python": venv_python, "prepared_at": time.time()}
        _secure_write(_path(directory, ".infraveil-runtime.json"), json.dumps(marker, sort_keys=True, separators=(",", ":")) + "\n")
        return venv_python
    finally:
        os.rmdir(lock_path)


def _ensure_runtime(home, script_path, argv):
    if _current_runtime_matches(home):
        return
    venv_python = _prepare_runtime(home)
    env = _sanitized_runtime_env(home)
    os.execve(venv_python, [venv_python, "-I", script_path] + list(argv), env)


def _crypto():
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey

    return serialization, Ed25519PrivateKey, Ed25519PublicKey


def _generate_key(path):
    if os.path.exists(path):
        raise RuntimeError(f"Refusing to overwrite existing private key: {path}")
    serialization, Ed25519PrivateKey, _ = _crypto()
    private_key = Ed25519PrivateKey.generate()
    seed = private_key.private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()
    _secure_write(path, seed + "\n")
    return private_key


def _load_private_key(path):
    raw = _read_secret_file(path, "approval private key").lower()
    if not _HEX64.fullmatch(raw):
        raise RuntimeError("approval private key must be a 32-byte Ed25519 seed encoded as 64 hex characters")
    _, Ed25519PrivateKey, _ = _crypto()
    return Ed25519PrivateKey.from_private_bytes(bytes.fromhex(raw))


def _public_key_hex(private_key):
    serialization, _, _ = _crypto()
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw,
        serialization.PublicFormat.Raw,
    ).hex()


def _sign(private_key, value):
    normalized = str(value or "").strip().lower()
    if not _HEX64.fullmatch(normalized):
        raise RuntimeError("value must be exactly 64 hexadecimal characters")
    return private_key.sign(normalized.encode("utf-8")).hex()


def _json_api(base_url, method, path, body=None, headers=None, timeout=25):
    parsed = urllib.parse.urlparse(str(base_url or ""))
    host = (parsed.hostname or "").lower()
    if parsed.scheme != "https" and not (
        parsed.scheme == "http" and host in {"127.0.0.1", "localhost", "::1"}
    ):
        return 0, {"error": "Refusing to send an Infraveil capability over a non-HTTPS control-plane URL"}
    data = json.dumps(body).encode("utf-8") if body is not None else None
    request = urllib.request.Request(base_url.rstrip("/") + path, data=data, method=method)
    request.add_header("User-Agent", TOOL_USER_AGENT)
    request.add_header("Accept", "application/json")
    if data is not None:
        request.add_header("Content-Type", "application/json")
    for key, value in (headers or {}).items():
        if value:
            request.add_header(key, str(value))
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.status, json.loads(response.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        try:
            return exc.code, json.loads(exc.read().decode("utf-8") or "{}")
        except Exception:
            return exc.code, {}
    except Exception as exc:
        return 0, {"error": str(exc)}


def _approval_api(config, token, method, path, body=None):
    return _json_api(
        config["base_url"],
        method,
        path,
        body,
        {"X-Infraveil-Approval-Token": token},
    )


def _bootstrap_api(config, token, method, path, body=None):
    return _json_api(
        config["base_url"],
        method,
        path,
        body,
        {"X-Infraveil-Bootstrap-Token": token},
    )


def _log(config, message):
    line = time.strftime("%Y-%m-%dT%H:%M:%S%z") + "  " + message
    print(line)
    path = config.get("log")
    if path:
        try:
            with open(path, "a", encoding="utf-8") as handle:
                handle.write(line + "\n")
            if os.name != "nt":
                os.chmod(path, 0o600)
        except Exception:
            pass


def _load_allowlist(path):
    if not path or not os.path.exists(path):
        return set()
    with open(path, encoding="utf-8") as handle:
        return {line.strip().lower() for line in handle if _HEX64.fullmatch(line.strip().lower())}


def _ask(prompt, default=""):
    suffix = f" [{default}]" if default else ""
    try:
        value = input(prompt + suffix + ": ").strip()
    except EOFError:
        return default
    return value or default


def _ask_yes_no(prompt, default=False):
    marker = "Y/n" if default else "y/N"
    answer = _ask(f"{prompt} ({marker})", "y" if default else "n").lower()
    return answer in {"y", "yes"}


def _choose_policy(config):
    policy = _ask("Approval policy (manual / allowlist / auto)", config.get("policy", "manual")).lower()
    if policy not in {"manual", "allowlist", "auto"}:
        raise RuntimeError("policy must be manual, allowlist, or auto")
    if policy == "auto":
        print(_col("AUTO signs every control-plane requested hash. The customer veto is not meaningful while AUTO is enabled.", "y"))
        if _ask("Type AUTO to enable", "").strip() != "AUTO":
            print(_col("Auto approval was not enabled; keeping manual policy.", "y"))
            policy = "manual"
    if policy == "allowlist":
        allowlist_path = config["allowlist_file"]
        if not os.path.exists(allowlist_path):
            _secure_write(allowlist_path, "")
        print(f"Add one approved SHA-256 hash per line to {allowlist_path}")
    config["policy"] = policy
    return policy


def _choose_setup_policy(config):
    print(_col("\nRelease approvals", "b"))
    print("Manual review preserves this machine's independent veto over each new release hash.")
    print("Automatic approval signs every control-plane requested hash and removes that practical veto.")
    automatic = _ask("Type AUTO to enable automatic approval, or press Enter for manual", "").strip() == "AUTO"
    config["policy"] = "auto" if automatic else "manual"
    if automatic:
        print(_col("Automatic approval enabled. Use --menu to switch back to manual review.", "y"))
    else:
        print(_col("Manual approval enabled. Pending release hashes will require confirmation.", "c"))
    return config["policy"]


def _scrub_bootstrap_token(paths, token):
    if not token:
        return
    for path in dict.fromkeys(os.path.abspath(value) for value in paths if value):
        try:
            with open(path, encoding="utf-8") as handle:
                source = handle.read()
            exact = f'EMBEDDED_BOOTSTRAP_TOKEN = {json.dumps(token)}'
            replacement = 'EMBEDDED_BOOTSTRAP_TOKEN = ""'
            if exact in source:
                _secure_write(path, source.replace(exact, replacement, 1))
                if os.name != "nt":
                    os.chmod(path, 0o700)
        except Exception:
            pass


def guided_setup(home, config, source_script):
    print(_col("\nINFRAVEIL TRUST CONSOLE — guided setup\n", "b"))
    print(f"Managed directory: {home}")
    token = BOOTSTRAP_TOKEN or os.environ.get("INFRAVEIL_BOOTSTRAP_TOKEN", "").strip()
    if not token:
        token = getpass.getpass("Paste the one-use bootstrap code from the dashboard (hidden): ").strip()
    if len(token) < 32:
        raise RuntimeError("No valid bootstrap capability is available. Download a fresh Trust Console from the dashboard.")

    key_file = config["key_file"]
    if os.path.exists(key_file):
        private_key = _load_private_key(key_file)
        print(_col("Using the existing local approval key.", "g"))
    else:
        private_key = _generate_key(key_file)
        print(_col(f"Created customer approval key: {key_file}", "g"))
    public_key = _public_key_hex(private_key)

    status, challenge_body = _bootstrap_api(
        config,
        token,
        "POST",
        "/client/api/trust-console/challenge",
        {"pubkey": public_key},
    )
    if status != 200:
        raise RuntimeError(challenge_body.get("error") or f"bootstrap challenge failed (HTTP {status})")
    challenge = str(challenge_body.get("challenge") or "").lower()
    signature = _sign(private_key, challenge)

    status, complete = _bootstrap_api(
        config,
        token,
        "POST",
        "/client/api/trust-console/complete",
        {
            "pubkey": public_key,
            "challenge": challenge,
            "signature": signature,
            "platform": "windows" if os.name == "nt" else "linux",
        },
    )
    if status != 200:
        raise RuntimeError(complete.get("error") or f"bootstrap completion failed (HTTP {status})")
    if str(complete.get("registered_pubkey") or "").lower() != public_key:
        raise RuntimeError("control plane registered a different approval public key")

    approval_token = str(complete.get("approval_token") or "")
    if len(approval_token) < 32:
        raise RuntimeError("bootstrap response did not contain a valid scoped approval token")
    _secure_write(config["token_file"], approval_token + "\n")
    config["workspace_username"] = str(complete.get("username") or config.get("workspace_username") or "")
    config["launcher_host_id"] = str(complete.get("launcher_host_id") or config.get("launcher_host_id") or "")
    config["pending_install_token"] = str(complete.get("install_token") or "")
    config["pending_install_url"] = str(complete.get("install_url") or "")
    config["pending_install_expires_at"] = float(complete.get("install_expires_at") or 0)
    config.pop("reviewed_launcher_source_hash", None)
    _save_config(home, config)
    _scrub_bootstrap_token([source_script, __file__, _installed_script(home)], token)
    # Basic setup never turns a setup confirmation into permission for future
    # releases. Automatic/allowlist policies remain explicit advanced choices.
    config["policy"] = "manual"
    print(_col("\nNew releases will stay paused until you review them.", "c"))
    _save_config(home, config)
    _prepare_approval_automation(home, config)

    print(_col("\nTrust enrollment complete.", "g"))
    print(f"Public key: {public_key}")
    print(f"Scoped approval token: stored in {config['token_file']}")
    print("The private key stayed on this machine.")
    return complete


def _verify_launcher(body, headers):
    source_hash = hashlib.sha256(body).hexdigest()
    reported_hash = str(headers.get("X-Infraveil-Launcher-Source-SHA256") or "").strip().lower()
    if not reported_hash or not _HEX64.fullmatch(reported_hash) or reported_hash != source_hash:
        raise RuntimeError("launcher download hash did not match the signed response metadata")
    signature = str(headers.get("X-Infraveil-Launcher-Ed25519") or "").strip().lower()
    if not RELEASE_PUBLIC_KEY or not _HEX64.fullmatch(RELEASE_PUBLIC_KEY) or not _HEX128.fullmatch(signature):
        raise RuntimeError("launcher download did not include a verifiable Infraveil release signature")
    _, _, Ed25519PublicKey = _crypto()
    try:
        Ed25519PublicKey.from_public_bytes(bytes.fromhex(RELEASE_PUBLIC_KEY)).verify(
            bytes.fromhex(signature), source_hash.encode("utf-8")
        )
    except Exception as exc:
        raise RuntimeError("launcher release signature verification failed") from exc
    return source_hash


def run_installed_launcher(home, config):
    launcher_path = str(config.get("launcher_file") or "")
    if not launcher_path or not os.path.isfile(launcher_path):
        raise RuntimeError("The launcher is not installed on this machine. Download a fresh Trust Console from the dashboard first.")
    print(_col(f"Starting the installed launcher at {launcher_path}", "c"))
    if config.get("policy") == "auto":
        print(_col("Your advanced AUTO policy is still enabled: it signs future requested hashes and removes the practical veto. Use --menu to return to manual review.", "y"))
    elif config.get("policy") == "allowlist":
        print("Your advanced allowlist policy remains active; only explicitly listed hashes are preapproved.")
    else:
        print("Later changes are not automatically approved.")
    print("To review releases, open a second terminal and run:")
    review_command = [sys.executable, _installed_script(home), "--once", "--home", home]
    if os.name == "nt":
        print("  " + subprocess.list2cmdline(review_command))
    else:
        import shlex
        print("  " + shlex.join(review_command))
    env = _sanitized_runtime_env(home)
    return subprocess.call(
        [sys.executable, "-I", launcher_path],
        cwd=os.path.dirname(launcher_path),
        env=env,
    )


def install_launcher(home, config, run_after=True):
    token = str(config.get("pending_install_token") or "")
    expires_at = float(config.get("pending_install_expires_at") or 0)
    install_url = str(config.get("pending_install_url") or "")
    username = str(config.get("workspace_username") or "")
    reviewed_hash = str(config.get("reviewed_launcher_source_hash") or "")
    selected_host = str(config.get("launcher_host_id") or "")
    if not _HEX64.fullmatch(reviewed_hash) or not selected_host:
        raise RuntimeError("Review this server's named releases before installing it. Run the console normally or use --once.")
    if len(token) < 32 or not install_url or not username or expires_at <= time.time():
        raise RuntimeError("The one-use launcher ticket is missing or expired. Download a fresh Trust Console from the dashboard.")
    nonce = os.urandom(16).hex()
    request = urllib.request.Request(install_url, data=b"", method="POST")
    request.add_header("User-Agent", TOOL_USER_AGENT)
    request.add_header("X-Infraveil-User", username)
    request.add_header("X-Infraveil-Install-Token", token)
    request.add_header("X-Infraveil-Nonce", nonce)
    try:
        with urllib.request.urlopen(request, timeout=40) as response:
            body = response.read()
            headers = response.headers
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"launcher download failed (HTTP {exc.code})") from exc
    source_hash = _verify_launcher(body, headers)
    if source_hash != reviewed_hash or str(headers.get("X-Infraveil-Launcher-Host-ID") or "") != selected_host:
        raise RuntimeError("The launcher download does not match the server and exact release you reviewed. Nothing was installed or started. The one-use download ticket has been consumed: download a fresh Trust Console from this server's dashboard, run that new file, and review the new releases before installation.")
    launcher_path = config["launcher_file"]
    _secure_dir(os.path.dirname(launcher_path))
    _secure_write(launcher_path, body)
    if os.name != "nt":
        os.chmod(launcher_path, 0o700)
    config["pending_install_token"] = ""
    config["pending_install_url"] = ""
    config["pending_install_expires_at"] = 0
    _save_config(home, config)
    print(_col(f"Verified launcher {source_hash[:16]}… and installed it at {launcher_path}", "g"))
    if run_after:
        print(_col("The launcher is verified. Its own guided setup will continue in this terminal.", "c"))
        return run_installed_launcher(home, config)
    return 0


def run_or_install_launcher(home, config):
    if os.path.isfile(config["launcher_file"]):
        return run_installed_launcher(home, config)
    return install_launcher(home, config, run_after=True)


def _load_approval_token(config):
    return _read_secret_file(config["token_file"], "approval token")


def _decide(config, payload_hash, agents, allowlist):
    policy = config.get("policy", "manual")
    if policy == "auto":
        return True
    if policy == "allowlist":
        return payload_hash in allowlist
    identities = ", ".join(item.get("name") or item.get("agent_id") or item.get("launcher_host_id") or "?" for item in agents)
    print(f"\nRelease awaiting approval:\n  hash: {payload_hash}\n  requested by: {identities or '(identity unavailable)'}")
    return _ask_yes_no("Approve this exact hash", False)


def _submit_batch(config, token, approvals):
    for attempt in range(APPROVAL_RETRY_ATTEMPTS):
        status, body = _approval_api(
            config,
            token,
            "POST",
            "/client/api/release-approval/approve-batch",
            {"approvals": approvals},
        )
        if status != 429:
            return status, body
        retry_after = max(1, min(30, int(body.get("retry_after") or 2**attempt)))
        if attempt + 1 < APPROVAL_RETRY_ATTEMPTS:
            time.sleep(retry_after)
    return status, body


def _selected_release_snapshot(body, config):
    """Map protocol identities, never approval from a name or unbound hash."""
    host_id = str(config.get("launcher_host_id") or "").strip()
    if not host_id:
        raise RuntimeError("This console has no selected server. Download a fresh console from that server's dashboard.")
    raw_pending = body.get("pending")
    if not isinstance(raw_pending, list) or any(not _HEX64.fullmatch(str(value)) for value in raw_pending):
        raise RuntimeError("The control plane returned an invalid release list; nothing was signed.")
    pending = set(raw_pending)
    launchers = body.get("launchers")
    agents = body.get("agents")
    if not isinstance(launchers, list) or not isinstance(agents, list):
        raise RuntimeError("Named release information is missing; nothing was signed.")
    selected_hosts = [row for row in launchers if isinstance(row, dict) and str(row.get("launcher_host_id") or "") == host_id]
    if len(selected_hosts) != 1:
        raise RuntimeError("The selected server is missing or ambiguous; nothing was signed.")
    components = []
    outside = set()
    unbound = set()

    def add(row, kind, identity, field, selected, bound):
        value = str(row.get(field) or "")
        if not value:
            return
        if not _HEX64.fullmatch(value):
            raise RuntimeError("A named component has an invalid release hash; nothing was signed.")
        if not bound or not identity:
            unbound.add(value)
            return
        if not selected:
            outside.add(value)
            return
        components.append((kind, identity, str(row.get("name") or identity), str(row.get("target_runtime_version") or ""), value))

    for row in launchers:
        if isinstance(row, dict):
            identity = str(row.get("launcher_host_id") or "")
            install_field = "install_source_hash" if row.get("install_source_hash") else "runtime_source_hash"
            add(row, "Server controller", identity, install_field, identity == host_id, bool(identity))
    for row in agents:
        if isinstance(row, dict):
            identity = str(row.get("agent_id") or "")
            assigned_host = str(row.get("launcher_host_id") or "")
            selected = assigned_host == host_id
            add(row, "App runtime", identity, "runtime_source_hash", selected, bool(assigned_host))
            add(row, "Application release", identity, "payload_hash", selected, bool(assigned_host))
    components = tuple(sorted(set(components)))
    identities = {}
    for component in components:
        key = component[:2]
        if key in identities and identities[key] != component:
            raise RuntimeError("A named component has conflicting release information; nothing was signed.")
        identities[key] = component
    selected_hashes = {component[4] for component in components}
    install_hash = str(selected_hosts[0].get("install_source_hash") or selected_hosts[0].get("runtime_source_hash") or "")
    if not _HEX64.fullmatch(install_hash):
        raise RuntimeError("The selected server's exact install release is unavailable. Nothing was signed or started.")
    install_approved = selected_hosts[0].get("install_source_approved") is True
    required_hashes = pending & selected_hashes
    if not install_approved:
        required_hashes.add(install_hash)
    ambiguous = required_hashes & (outside | unbound)
    if ambiguous:
        raise RuntimeError("A release is also bound outside this server or has an unbound identity. Review it in the advanced console; nothing was signed.")
    unknown = pending - selected_hashes - outside
    required = tuple(sorted(required_hashes))
    held = tuple(sorted(pending - selected_hashes))
    return {
        "host_id": host_id,
        "host_name": str(selected_hosts[0].get("name") or host_id),
        "components": components,
        "required": required,
        "held": held,
        "unbound": tuple(sorted((pending & unbound) | unknown)),
        "launcher_source_hash": install_hash,
    }


def _read_selected_releases(config, token, public_key):
    status, body = _approval_api(config, token, "GET", "/client/api/release-approval/pending")
    if status != 200 or not isinstance(body, dict):
        raise RuntimeError(f"Could not read the current releases (HTTP {status}). Nothing was signed; run --once to retry.")
    if str(body.get("registered_pubkey") or "").lower() != public_key:
        raise RuntimeError("The workspace approval key does not match this local key. Nothing was signed.")
    return _selected_release_snapshot(body, config)


def _confirm_named_release_set(snapshot):
    required = set(snapshot["required"])
    components = [component for component in snapshot["components"] if component[4] in required]
    print(_col(f"\nRelease review for {snapshot['host_name']}", "b"))
    for index, (kind, _identity, name, version, _digest) in enumerate(components, 1):
        version_text = f" — version {version}" if version and kind != "Application release" else ""
        print(f"  {index}) {name}: {kind.lower()}{version_text}")
    print("Approving this list signs only these current releases. Future or changed releases still need review.")
    while True:
        answer = _ask("Approve the displayed releases? (y/N, or details to inspect exact hashes)", "n").lower()
        if answer in {"details", "d"}:
            for kind, identity, name, version, digest in components:
                print(f"  {name} | {kind} | {identity} | {version or 'current package'}\n    SHA-256 {digest}")
            continue
        return answer in {"y", "yes"}


def _review_selected_releases(config):
    private_key = _load_private_key(config["key_file"])
    public_key = _public_key_hex(private_key)
    token = _load_approval_token(config)
    snapshot = _read_selected_releases(config, token, public_key)
    if snapshot["held"]:
        _log(config, f"HELD {len(snapshot['held'])} other or unbound release hashes; this review does not approve them.")
    if snapshot["unbound"]:
        raise RuntimeError("Some releases have no confirmed server/component identity. They remain held; setup is not complete and nothing was signed.")
    if not snapshot["required"]:
        _log(config, "No pending releases were reported for this selected server.")
        config["reviewed_launcher_source_hash"] = snapshot["launcher_source_hash"]
        return 0
    if not _confirm_named_release_set(snapshot):
        raise RuntimeError("Release approval was cancelled. Nothing was signed or started; run --once when ready.")
    current = _read_selected_releases(config, token, public_key)
    if current["unbound"] or (current["components"], current["required"]) != (snapshot["components"], snapshot["required"]):
        raise RuntimeError("The displayed releases changed during review. Nothing was signed; run --once to review the new list.")
    approvals = [{"payload_hash": digest, "signature": _sign(private_key, digest)} for digest in snapshot["required"]]
    for offset in range(0, len(approvals), APPROVAL_BATCH_SIZE):
        batch = approvals[offset:offset + APPROVAL_BATCH_SIZE]
        status, response = _submit_batch(config, token, batch)
        expected = {entry["payload_hash"] for entry in batch}
        acknowledged = response.get("approved") if isinstance(response, dict) else None
        if status != 200 or not isinstance(acknowledged, list) or set(acknowledged) != expected:
            raise RuntimeError(f"The exact approval batch was not confirmed (HTTP {status}). Setup is not complete; run --once to reconcile.")
    final = _read_selected_releases(config, token, public_key)
    if final["unbound"] or final["components"] != snapshot["components"] or final["required"]:
        raise RuntimeError("The selected releases are still pending or changed after approval. Setup is not complete; run --once to review them.")
    _log(config, f"APPROVED {len(approvals)} displayed exact release hashes. Future changes remain manual.")
    config["reviewed_launcher_source_hash"] = final["launcher_source_hash"]
    return 0


def approve_pending(config, once=False):
    if config.get("policy", "manual") == "manual":
        while True:
            _review_selected_releases(config)
            if once:
                return 0
            _sleep(config)
    private_key = _load_private_key(config["key_file"])
    public_key = _public_key_hex(private_key)
    token = _load_approval_token(config)
    _log(config, f"trust console started | policy={config.get('policy')} | public_key={public_key[:16]}…")
    while True:
        status, body = _approval_api(config, token, "GET", "/client/api/release-approval/pending")
        if status in {401, 403}:
            _log(config, "ERROR: scoped approval token rejected. Download a fresh Trust Console to reconnect.")
            return 1 if once else _sleep(config)
        if status != 200:
            _log(config, f"WARN: pending release check failed (HTTP {status}): {body.get('error', '')}")
            if once:
                return 1
            _sleep(config)
            continue
        registered = str(body.get("registered_pubkey") or "").lower()
        if registered != public_key:
            _log(config, "REFUSING: the workspace public key does not match this local private key.")
            return 1
        pending = [str(value).lower() for value in body.get("pending") or [] if _HEX64.fullmatch(str(value).lower())]
        identities = {}
        for item in list(body.get("agents") or []) + list(body.get("launchers") or []):
            for key in ("payload_hash", "runtime_source_hash"):
                payload_hash = str(item.get(key) or "").lower()
                if payload_hash:
                    identities.setdefault(payload_hash, []).append(item)
        allowlist = _load_allowlist(config.get("allowlist_file"))
        approvals = []
        if not pending:
            _log(config, "ok: nothing pending; desired releases are approved.")
        for payload_hash in pending:
            if _decide(config, payload_hash, identities.get(payload_hash, []), allowlist):
                approvals.append({"payload_hash": payload_hash, "signature": _sign(private_key, payload_hash)})
            else:
                _log(config, f"HELD {payload_hash[:16]}…")
        for offset in range(0, len(approvals), APPROVAL_BATCH_SIZE):
            batch = approvals[offset : offset + APPROVAL_BATCH_SIZE]
            status, response = _submit_batch(config, token, batch)
            if status != 200:
                _log(config, f"FAILED signed batch (HTTP {status}): {response.get('error', '')}")
                if once:
                    return 1
            else:
                _log(config, f"APPROVED {int(response.get('approved_count') or len(batch))} exact release hashes")
        if once:
            return 0
        _sleep(config)


def _approval_service_slug(config):
    value = str(config.get("workspace_username") or config.get("launcher_host_id") or "workspace").lower()
    value = re.sub(r"[^a-z0-9.-]+", "-", value).strip(".-")
    return (value or "workspace")[:48]


def _approval_service_label(config):
    return "com.infraveil.approver." + _approval_service_slug(config)


def _mac_approval_service(home, config):
    logs_dir = _path(home, "logs")
    return {
        "Label": _approval_service_label(config),
        "ProgramArguments": [
            _venv_python(home),
            "-I",
            "-u",
            _installed_script(home),
            "--watch",
            "--home",
            home,
        ],
        "WorkingDirectory": home,
        "EnvironmentVariables": {
            "INFRAVEIL_CONTROL_HOME": home,
            "PATH": "/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin",
        },
        "RunAtLoad": True,
        "KeepAlive": {"SuccessfulExit": False},
        "ThrottleInterval": 10,
        "ProcessType": "Background",
        "Umask": 0o077,
        "StandardOutPath": _path(logs_dir, "approver.stdout.log"),
        "StandardErrorPath": _path(logs_dir, "approver.stderr.log"),
    }


def _start_auto_approval_watcher(home, config):
    if config.get("policy") != "auto":
        return
    _secure_dir(_path(home, "logs"))
    if platform.system().lower() == "darwin":
        label = _approval_service_label(config)
        domain = f"gui/{os.getuid()}"
        service_path = os.path.expanduser(f"~/Library/LaunchAgents/{label}.plist")
        service = _mac_approval_service(home, config)
        _secure_write(service_path, plistlib.dumps(service, fmt=plistlib.FMT_XML).decode("utf-8"))
        subprocess.run(
            ["launchctl", "bootout", f"{domain}/{label}"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
        subprocess.run(
            ["launchctl", "enable", f"{domain}/{label}"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
        subprocess.check_call(["launchctl", "bootstrap", domain, service_path])
        print(_col("Automatic release approval is running in the background.", "g"))
        return

    pid_file = _path(home, "approval-watcher.pid")
    try:
        existing_pid = int(_read_secret_file(pid_file, "approval watcher PID") or 0)
        if existing_pid > 1:
            os.kill(existing_pid, 0)
            return
    except Exception:
        pass
    stdout_path = _path(home, os.path.join("logs", "approver.stdout.log"))
    stderr_path = _path(home, os.path.join("logs", "approver.stderr.log"))
    popen_options = {
        "cwd": home,
        "env": _sanitized_runtime_env(home),
        "stdin": subprocess.DEVNULL,
        "close_fds": True,
    }
    if os.name == "nt":
        popen_options["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP | subprocess.DETACHED_PROCESS
    else:
        popen_options["start_new_session"] = True
    with open(stdout_path, "ab", buffering=0) as stdout_handle, open(stderr_path, "ab", buffering=0) as stderr_handle:
        process = subprocess.Popen(
            [_venv_python(home), "-I", "-u", _installed_script(home), "--watch", "--home", home],
            stdout=stdout_handle,
            stderr=stderr_handle,
            **popen_options,
        )
    _secure_write(pid_file, str(process.pid) + "\n")
    print(_col("Automatic release approval is running in the background for this login session.", "g"))


def _stop_auto_approval_watcher(home, config):
    if platform.system().lower() == "darwin":
        label = _approval_service_label(config)
        domain = f"gui/{os.getuid()}"
        service_path = os.path.expanduser(f"~/Library/LaunchAgents/{label}.plist")
        subprocess.run(
            ["launchctl", "bootout", f"{domain}/{label}"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )
        try:
            os.remove(service_path)
        except FileNotFoundError:
            pass
        return
    pid_file = _path(home, "approval-watcher.pid")
    try:
        process_id = int(_read_secret_file(pid_file, "approval watcher PID") or 0)
        if process_id > 1:
            os.kill(process_id, 15)
    except Exception:
        pass
    try:
        os.remove(pid_file)
    except FileNotFoundError:
        pass


def _prepare_approval_automation(home, config):
    if config.get("policy") == "auto":
        if approve_pending(config, once=True) != 0:
            raise RuntimeError("Could not verify the initial release-approval state")
        _start_auto_approval_watcher(home, config)
    else:
        _stop_auto_approval_watcher(home, config)
        if approve_pending(config, once=True) != 0:
            raise RuntimeError("Could not complete the manual release review")


def _sleep(config):
    time.sleep(max(5, int(config.get("interval") or 30)))
    return 0


def _status(home, config):
    print(_col("\nINFRAVEIL TRUST CONSOLE\n", "b"))
    print(f"  Managed home     {home}")
    print(f"  Approval key     {'READY' if os.path.isfile(config['key_file']) else 'NOT SET'}")
    print(f"  Approval token   {'READY' if os.path.isfile(config['token_file']) else 'NOT SET'}")
    print(f"  Policy           {config.get('policy', 'manual')}")
    print(f"  Launcher         {'INSTALLED' if os.path.isfile(config['launcher_file']) else 'NOT INSTALLED'}")
    print(f"  Workspace        {config.get('workspace_username') or 'not connected'}")


def interactive_menu(home, config, source_script):
    _enable_ansi()
    while True:
        _status(home, config)
        print("\n  1) Guided trust setup")
        print("  2) Sign one challenge or release hash")
        print("  3) Review pending releases once")
        print("  4) Watch for pending releases")
        print("  5) Choose approval policy")
        if os.path.isfile(config["launcher_file"]):
            print("  6) Run installed launcher on this machine")
        else:
            print("  6) Install and run launcher on this machine")
        print("  7) Show security model")
        print("  0) Quit")
        choice = _ask("Choose", "0").lower()
        try:
            if choice == "1":
                complete = guided_setup(home, config, source_script)
                if complete.get("install_token") and _ask_yes_no(
                    "Install the launcher on this same machine now (keep the approval key on a separate admin machine for the strongest veto)",
                    False,
                ):
                    install_launcher(home, config, run_after=True)
            elif choice == "2":
                value = _ask("64-character challenge or release hash").lower()
                print("Signature:\n  " + _sign(_load_private_key(config["key_file"]), value))
            elif choice == "3":
                approve_pending(config, once=True)
            elif choice == "4":
                approve_pending(config, once=False)
            elif choice == "5":
                _choose_policy(config)
                _save_config(home, config)
                _prepare_approval_automation(home, config)
            elif choice == "6":
                _review_selected_releases(config)
                run_or_install_launcher(home, config)
            elif choice == "7":
                print("\nThe private Ed25519 key stays in this directory. Infraveil receives only the public key and signatures over exact SHA-256 hashes.")
                print("Manual and allowlist policies preserve a customer veto. Auto policy intentionally gives that veto up while enabled.")
                print("For the strongest boundary, keep this console on an admin workstation and run the launcher on a different server.\n")
            elif choice in {"0", "q", "quit", "exit"}:
                return 0
        except KeyboardInterrupt:
            print("\nCancelled.")
        except Exception as exc:
            print(_col(f"ERROR: {exc}", "r"))


def _run_state_aware_default(home, config, source_script):
    enrolled = os.path.isfile(config["key_file"]) and os.path.isfile(config["token_file"])
    # A new dashboard capability must be honored even after an earlier setup
    # consumed its ticket. guided_setup reuses, never rotates, the local key.
    if BOOTSTRAP_TOKEN or not enrolled:
        if not BOOTSTRAP_TOKEN:
            print(_col("This is the public Trust Console source, so it has no workspace bootstrap capability.", "y"))
            print("Open Connect & review in the Infraveil dashboard and click Connect server.")
            return 1
        print(_col("Fresh Trust Console download detected. Starting secure workspace setup automatically.", "c"))
        complete = guided_setup(home, config, source_script)
        if complete.get("install_token"):
            print(_col("Trust is ready. Installing and starting the launcher now.", "c"))
            return install_launcher(home, config, run_after=True)
        print(_col("Trust setup is complete, but the launcher ticket was not returned. Download a fresh Trust Console to retry installation.", "y"))
        return 0

    install_ready = (
        not os.path.isfile(config["launcher_file"])
        and len(str(config.get("pending_install_token") or "")) >= 32
        and float(config.get("pending_install_expires_at") or 0) > time.time()
    )
    if install_ready:
        print(_col("Trust enrollment is complete and the launcher install is ready.", "c"))
        _prepare_approval_automation(home, config)
        if config.get("policy", "manual") != "manual":
            # Advanced policy processing is not itself a selected-host install
            # proof. Reconcile the named current set before the install gate.
            _review_selected_releases(config)
        return install_launcher(home, config, run_after=True)
    if os.path.isfile(config["launcher_file"]):
        print(_col("Trust and launcher are ready. Starting Infraveil.", "c"))
        _prepare_approval_automation(home, config)
        return run_installed_launcher(home, config)
    print(_col("The launcher is not installed and its one-use install ticket is missing or expired.", "y"))
    print("Download a fresh Trust Console from the dashboard and run that new file. Your existing approval key will be reused.")
    return 1


def _parser():
    parser = argparse.ArgumentParser(description="Infraveil Trust Console")
    parser.add_argument("--home", help="managed console directory (default: ./infraveil-control)")
    parser.add_argument("--menu", action="store_true", help="open the advanced numbered trust console")
    parser.add_argument("--setup", action="store_true", help="complete guided dashboard bootstrap")
    parser.add_argument("--genkey", action="store_true", help="generate the local approval key and exit")
    parser.add_argument("--out", help="private-key output path for --genkey")
    parser.add_argument("--sign", "--hash", dest="sign_value", help="sign one 64-character challenge or release hash")
    parser.add_argument("--key-file", help="private key used by --sign")
    parser.add_argument("--once", action="store_true", help="review pending releases once")
    parser.add_argument("--watch", action="store_true", help="continuously review pending releases")
    parser.add_argument("--install-launcher", action="store_true", help="consume the pending one-use launcher ticket")
    parser.add_argument("--no-run", action="store_true", help="download and verify the launcher without running it")
    parser.add_argument("--prepare-runtime", action="store_true", help="prepare only the private hash-locked runtime without approval or key actions")
    return parser


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    args = _parser().parse_args(argv)
    home = _control_home(args.home)
    if args.prepare_runtime:
        python_path = _prepare_runtime(home)
        print(json.dumps({"python": python_path, "lock_sha256": _runtime_lock_identity(), "verified": True}, sort_keys=True))
        return 0
    _secure_dir(home)
    installed = _install_self(home)
    source_script = os.path.realpath(__file__)
    if BOOTSTRAP_TOKEN and os.path.abspath(source_script) != os.path.abspath(installed):
        _scrub_bootstrap_token([source_script], BOOTSTRAP_TOKEN)
    _ensure_runtime(home, installed, argv)
    config = _load_config(home)
    source_script = os.path.realpath(__file__)

    if args.menu:
        return interactive_menu(home, config, source_script)

    if args.genkey:
        path = os.path.abspath(os.path.expanduser(args.out or config["key_file"]))
        private_key = _generate_key(path)
        print(f"PRIVATE KEY written to {path}; keep it private and backed up.")
        print("PUBLIC KEY:\n  " + _public_key_hex(private_key))
        return 0
    if args.sign_value:
        key_file = os.path.abspath(os.path.expanduser(args.key_file or config["key_file"]))
        print("SIGNATURE:\n  " + _sign(_load_private_key(key_file), args.sign_value))
        return 0
    if args.setup:
        complete = guided_setup(home, config, source_script)
        print("Run this file again to review approvals or install the launcher.")
        return 0 if complete else 1
    if args.once or args.watch:
        return approve_pending(config, once=args.once)
    if args.install_launcher:
        _review_selected_releases(config)
        return install_launcher(home, config, run_after=not args.no_run)
    return _run_state_aware_default(home, config, source_script)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        print("\nStopped. No unsigned release was approved.")
        raise SystemExit(130)
    except Exception as exc:
        print(_col(f"ERROR: {exc}", "r"), file=sys.stderr)
        raise SystemExit(1)
